return items.map(item => {
    // Accedemos directo al objeto productos
    const producto = item.json.productos;

    // Validamos que el campo Color exista
    let rawColor = producto.Color;
    if (!rawColor) {
        return {
            json: {
                ...item.json,
                parsedColors: [],
                error: '❌ Campo Color no encontrado'
            }
        };
    }

    // Limpiar el string
    const cleaned = rawColor
        .replace(/\n/g, '')               // elimina saltos de línea
        .replace(/""/g, '"')              // corrige comillas dobles
        .replace(/,\s*]$/, ']')           // elimina coma final antes de cerrar array
        .trim();

    let parsedColors = [];
    try {
        parsedColors = JSON.parse(cleaned);
    } catch (error) {
        console.log("❌ Error al parsear:", error.message);
    }

    // Retornamos el mismo objeto, con parsedColors incluido
    return {
        json: {
            ...item.json,
            productos: {
                ...producto,
                parsedColors
            }
        }
    };
});

