// Verificar si 'data' existe en el item
if (items.length === 0 || !items[0].json.data) {
    return [{ json: { message: 'No se encontró el campo "data" en los items.' } }];
}

// Extraer los productos de la propiedad 'data'
const productNamesList = items[0].json.data;

// Crear un conjunto para almacenar productos únicos por nombre
const uniqueProductNames = new Set();

// Filtrar solo los productos únicos por nombre y retornar el item completo
const uniqueProducts = productNamesList.filter(item => {
    const productName = item['Nombre de producto']; // Accedemos al nombre del producto

    if (!uniqueProductNames.has(productName)) {
        uniqueProductNames.add(productName); // Agregar al conjunto si no está presente
        return true; // Retornar el item completo si es único
    }
    return false; // No retornar si ya está en el conjunto
});

// Mostrar los productos únicos para depuración
console.log('Productos únicos:', uniqueProducts);

// Retornar los productos únicos englobados en un solo objeto
return [{
    json: {
        productos: uniqueProducts // Englobar los productos únicos dentro de la propiedad 'productos'
    }
}];

// Validación de entrada
if (items.length === 0 || !items[0].json.ia_url || !items[0].json.recent_urls) {
	return [{
		json: {
			error: 'Faltan los campos "ia_url" o "recent_urls".'
		}
	}];
}

// Función para calcular similitud (distancia de Levenshtein normalizada)
function similarity(a, b) {
	const lengthA = a.length;
	const lengthB = b.length;
	const dp = Array.from({ length: lengthA + 1 }, () => Array(lengthB + 1).fill(0));

	for (let i = 0; i <= lengthA; i++) dp[i][0] = i;
	for (let j = 0; j <= lengthB; j++) dp[0][j] = j;

	for (let i = 1; i <= lengthA; i++) {
		for (let j = 1; j <= lengthB; j++) {
			const cost = a[i - 1] === b[j - 1] ? 0 : 1;
			dp[i][j] = Math.min(
				dp[i - 1][j] + 1,
				dp[i][j - 1] + 1,
				dp[i - 1][j - 1] + cost
			);
		}
	}

	const distance = dp[lengthA][lengthB];
	const maxLen = Math.max(lengthA, lengthB);
	return 1 - distance / maxLen; // Similitud entre 0 y 1
}

// Extraer los datos
const aiUrl = items[0].json.ia_url;
const recentUrls = items[0].json.recent_urls;

let bestMatch = null;
let highestScore = 0;

// Comparar cada URL reciente con la generada por la IA
for (const url of recentUrls) {
	const score = similarity(aiUrl, url);
	if (score > highestScore) {
		highestScore = score;
		bestMatch = url;
	}
}

// Resultado final
return [{
	json: {
		original_url: aiUrl,
		best_match_url: bestMatch,
		similarity_score: highestScore
	}
}];

